// Previs section: the Unreal shot list (previs/shotlist.json, generated by tools/previs-shotlist.mjs)
// merged with data.previs.media. Each slot shows either the rendered previs video (once the owner has
// rendered and encoded it) or a top-down plan of the shot (ui/plot.js) with a camera-report slate and
// a "PREVIS PENDING: Unreal / Sequencer" tag. A missing or unreadable shot list hides the grid.
//
//   import { mountPrevis } from './previs.js';
//   await mountPrevis(document.querySelector('[data-previs-grid]'), data);
//
// Unreal → plan coordinates (shotlist axes: X forward, the subject at the origin facing −X, Y right,
// cm): plan x = Y / 100 (screen right), plan y = −X / 100 (toward the camera). Lights come from
// core/presets.js, the same table the shot list and the Light study are generated from.

import { html, put, esc, safeUrl, MOVE_NAMES as MOVES } from './render.js';
import { renderPlan } from '../ui/plot.js';
import { LIGHTING_PRESETS } from '../core/presets.js';
import { isReducedMotion, onMotionChange } from '../core/motion-pref.js';

const fmt1 = v => (Math.round(v * 10) / 10).toFixed(1);
const toPlan = loc => ({ x: (loc[1] ?? 0) / 100, y: -(loc[0] ?? 0) / 100 });

/** Camera positions (plan metres) for a shot's keys; handles plain loc keys and a pivot rig. */
function cameraPath(shot) {
  const keys = Array.isArray(shot.keys) ? shot.keys : [];
  const pts = keys.filter(k => Array.isArray(k.loc)).map(k => toPlan(k.loc));
  if (pts.length) return pts;
  // Orbit rig: camera parented to a pivot at the subject, keyed by pivot yaw.
  const rig = shot.rig ?? shot.pivot ?? null;
  const off = rig?.offset ?? rig?.cameraOffset ?? shot.offset;
  const yaws = keys.map(k => k.pivotYaw ?? k.yaw ?? k.rot?.yaw).filter(Number.isFinite);
  if (Array.isArray(off) && yaws.length >= 2) {
    const piv = rig?.loc ?? [0, 0, 0];
    const out = [];
    const [a, b] = [yaws[0], yaws.at(-1)];
    for (let i = 0; i <= 24; i++) {
      const yaw = ((a + (b - a) * (i / 24)) * Math.PI) / 180;
      const x = piv[0] + off[0] * Math.cos(yaw) - off[1] * Math.sin(yaw);
      const y = piv[1] + off[0] * Math.sin(yaw) + off[1] * Math.cos(yaw);
      out.push(toPlan([x, y]));
    }
    return out;
  }
  return [];
}

/** Horizontal FOV in degrees for a focal length on the shot list's filmback. */
const hfov = (focal, sensorW = 24.89) => (2 * Math.atan(sensorW / 2 / focal) * 180) / Math.PI;

function slateLines(shot, list) {
  const lens = shot.lens ?? {};
  const keys = Array.isArray(shot.keys) ? shot.keys : [];
  const foc = keys.map(k => k.focus).filter(Number.isFinite);
  const focusText = foc.length >= 2 && foc[0] !== foc.at(-1) ? `⌀ ${fmt1(foc[0] / 100)}→${fmt1(foc.at(-1) / 100)} m`
    : Number.isFinite(lens.focus) ? `⌀ ${fmt1(lens.focus / 100)} m` : '';
  const focals = keys.map(k => k.focal).filter(Number.isFinite);
  const focalText = focals.length >= 2 && focals[0] !== focals.at(-1) ? `${+focals[0].toFixed(1)}→${+focals.at(-1).toFixed(1)}mm` : lens.focal ? `${lens.focal}mm` : '';
  const pr = LIGHTING_PRESETS[shot.lighting];
  const lt = list.lighting?.[shot.lighting] ?? {};
  const keyK = lt.key?.kelvin ?? pr?.lights?.find(l => l.role === 'key')?.kelvin;
  const wb = lt.cameraWB ?? pr?.cameraWB;
  const fb = /35/.test(list.filmback?.preset ?? 'Super 35') ? 'S35' : list.filmback.preset;
  return [
    [shot.mp, shot.move ?? MOVES[shot.mp], Number.isFinite(shot.durationS) && `${shot.durationS.toFixed(1)} s`].filter(Boolean).join(' · '),
    [fb, focalText, lens.tStop && `T${lens.tStop}`, focusText].filter(Boolean).join(' · '),
    [pr ? `${pr.label}${pr.mp ? ` ${pr.mp}` : ''}` : shot.lighting, keyK && `${keyK}K key`, wb && `${wb}K WB`].filter(Boolean).join(' · '),
  ];
}

function slotMarkup(shot, list, media) {
  const lines = slateLines(shot, list);
  const video = safeUrl(media?.video), poster = safeUrl(media?.poster);
  const dur = Number.isFinite(shot.durationS) ? `${shot.durationS.toFixed(1)} s` : '';
  return html`
    <li class="previs-slot" data-reveal data-shot="${shot.id}">
      <figure class="previs-slot__fig">
        <div class="previs-slot__frame frame" style="--ar:${list.output?.aspect ?? 2.39}">
          ${video ? html`<video class="previs-slot__video" muted playsinline loop preload="none" ${poster ? html`poster="${poster}"` : ''} aria-label="${`Previs render of ${shot.id}, ${shot.title ?? ''}`}"><source src="${video}"></video>`
            : html`<p class="previs-slot__corner previs-slot__corner--tl" aria-hidden="true">${shot.id} · Plan view</p><p class="previs-slot__corner previs-slot__corner--tr" aria-hidden="true">${shot.mp ?? ''} ${shot.move ?? MOVES[shot.mp] ?? ''}</p><svg class="previs-slot__plan" id="previs-plan-${esc(shot.id)}" data-plan preserveAspectRatio="xMidYMid meet"></svg>`}
        </div>
        <figcaption class="previs-slot__cap">
          <p class="previs-slot__title"><span class="previs-slot__id">${shot.id}</span> ${shot.title ?? shot.move ?? ''}</p>
          <p class="previs-slot__slate cam-label">${lines.map((l, k) => html`<span class="previs-slot__line${k ? '' : ' previs-slot__line--lead'}">${l}</span>`)}</p>
          <p class="previs-slot__tags">${video ? html`<span class="tag tag--live">Unreal render${dur ? ` · ${dur}` : ''}</span>` : html`<span class="tag">Previs pending: Unreal / Sequencer</span>`}</p>
          ${shot.notes ? html`<p class="previs-slot__notes">${shot.notes}</p>` : ''}
        </figcaption>
      </figure>
    </li>`;
}

function drawPlan(svg, shot, list) {
  const path = cameraPath(shot);
  const cam0 = path[0] ?? { x: 0, y: 4 };
  const pr = LIGHTING_PRESETS[shot.lighting];
  const focal = shot.lens?.focal ?? shot.keys?.[0]?.focal ?? 35;
  const { bounds } = renderPlan(svg, {
    camera: { x: cam0.x, y: cam0.y, fov: hfov(focal, list.filmback?.sensorWidth), label: `${shot.id} · ${focal}MM` },
    path: path.length > 1 ? path : null,
    subject: { r: 0.14 },
    lights: (pr?.lights ?? []).map(l => ({ role: l.role, az: l.az, el: l.el, dist: l.dist, kelvin: l.kelvin, size: l.size })),
    labels: { title: `Plan of previs shot ${shot.id}: ${shot.title ?? shot.move ?? ''}`, scale: true },
  });
  fitPlan(svg, bounds);
}

/**
 * Widen the square plan to the slot's own shape (16:9 on wide screens, square on phones, set in
 * site.css) so the rings run on to the edges, and keep a band clear at the top for the corner
 * labels. The plan's type is sized in plan units, so the frame's height decides its legibility.
 */
function fitPlan(svg, bounds) {
  if (!bounds) return;
  const frame = svg.parentElement;
  const fw = frame?.clientWidth || 16, fh = frame?.clientHeight || 9;
  const ar = fw / fh;
  const top = Math.min(0.2, 34 / fh), bottom = 0.03;   // ≈34 CSS px for the corner labels
  const h = bounds.maxY - bounds.minY;
  const H = h / (1 - top - bottom), W = Math.max(H * ar, bounds.maxX - bounds.minX);
  const cx = (bounds.minX + bounds.maxX) / 2;
  svg.setAttribute('viewBox', `${(cx - W / 2).toFixed(3)} ${(bounds.minY - H * top).toFixed(3)} ${W.toFixed(3)} ${H.toFixed(3)}`);
  svg.__planBounds = bounds;
}

/** Play videos while in view (hover on fine pointers); under reduced motion show the poster + controls. */
function wireVideos(grid) {
  const vids = [...grid.querySelectorAll('video')];
  if (!vids.length) return;
  const apply = () => {
    const reduced = isReducedMotion();
    for (const v of vids) { v.controls = reduced; if (reduced) v.pause(); }
  };
  apply();
  onMotionChange(apply);
  if (typeof IntersectionObserver === 'undefined') return;
  const io = new IntersectionObserver(entries => {
    for (const e of entries) {
      const v = e.target;
      if (isReducedMotion()) continue;
      if (e.intersectionRatio >= 0.6) v.play().catch(() => { /* autoplay refused: poster stays */ });
      else v.pause();
    }
  }, { threshold: [0, 0.6] });
  vids.forEach(v => io.observe(v));
}

export async function mountPrevis(grid, data) {
  if (!grid) return false;
  const rel = safeUrl(data?.previs?.shotlist) ?? 'previs/shotlist.json';
  let list;
  try {
    const res = await fetch(new URL(rel, document.baseURI), { cache: 'no-cache' });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    list = await res.json();
    if (!Array.isArray(list?.shots) || !list.shots.length) throw new Error('no shots');
  } catch (err) {
    console.info('[previs] shot list unavailable; the grid stays hidden.', err?.message ?? err);
    grid.hidden = true;
    return false;
  }
  const media = data.previs?.media ?? {};
  put(grid, html`${list.shots.map(s => slotMarkup(s, list, media[s.id]))}`);
  grid.hidden = false;   // plans fit their frame, so the frame must have a size first
  const plans = [];
  for (const shot of list.shots) {
    const svg = grid.querySelector(`[data-shot="${CSS.escape(shot.id)}"] svg[data-plan]`);
    if (!svg) continue;
    try { drawPlan(svg, shot, list); plans.push(svg); } catch (err) { console.warn('[previs] plan', shot.id, err); }
  }
  // Refit when a slot changes shape (phone ↔ tablet ↔ desktop, rotation).
  if (plans.length && typeof ResizeObserver !== 'undefined') {
    const ro = new ResizeObserver(entries => {
      for (const e of entries) { const svg = e.target.querySelector('svg[data-plan]'); if (svg?.__planBounds) fitPlan(svg, svg.__planBounds); }
    });
    plans.forEach(svg => ro.observe(svg.parentElement));
  }
  wireVideos(grid);
  return true;
}
